```yaml
name: Assign dependencies label

on:
  pull_request:
    types: [opened, reopened]

permissions:
  contents: read
  issues: write
  pull-requests: write

jobs:
  label:
    if: contains(['dependabot[bot]', 'transifex-integration[bot]', 'imgbot[bot]'], github.actor)
    runs-on: ubuntu-latest
    steps:
      - name: Add dependencies label
        uses: actions/github-script@v7
        with:
          script: |
            const prNumber = context.payload.pull_request.number;
            const labelName = ':heavy_check_mark: dependencies';

            // Check if the label is already present
            const { data: existingLabels } = await github.issues.listLabelsOnIssue({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber
            });

            const hasLabel = existingLabels.some(l => l.name === labelName);

            if (!hasLabel) {
              await github.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                labels: [labelName]
              });
            }
